     fn book(&mut self, phys_addr: PageAligned<PhysicalAddress>) -> Result<(), Error> {
         proof_decl! {
             let ghost pa: int = phys_addr@;
             let ghost old_self = *self;
         }
         let raw: usize = phys_addr.into_raw_value();
         let frame_number: usize = raw / mem::FRAME_SIZE;
